// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import type { Fact, WalkStep } from '@/app/demos/stage/types'

export type NetStatus = 'online' | 'lan' | 'offline' | 'nodata'
type NetEvent = { at: number; status: NetStatus; ip?: string }
type Sample = { at: number; status: NetStatus; latency: number | null }

export const STATUS_COLOR: Record<NetStatus, string> = {
  online: '#22c55e',
  lan: '#fbbf24',
  offline: '#f87171',
  nodata: '#64748b',
}
export const LATENCY_COLOR = '#818cf8'
export const LIVE_LABEL: Record<NetStatus, string> = {
  online: 'Online',
  lan: 'Wi-Fi/LAN OK, no Internet',
  offline: 'Offline',
  nodata: 'No data',
}
const SHORT: Record<NetStatus, string> = {
  online: 'Online',
  lan: 'LAN only',
  offline: 'Offline',
  nodata: 'No data',
}
const HUMAN: Record<NetStatus, string> = {
  online: 'Online',
  lan: 'No Internet connection. Wi-Fi/LAN OK',
  offline: 'No Internet connection',
  nodata: 'No data (monitor was off)',
}

const hms = (h: number, m: number, s: number) => ((h * 60 + m) * 60 + s) * 1000
export const IP = '203.0.113.42'
export const INTERVAL_S = 3
export const PING_HOST = 'www.google.com'
export const DATE = '10/24/2026'

export const STARTED = hms(9, 0, 0)
export const START = hms(9, 41, 58)
export const DROP = hms(9, 42, 10)
export const BACK = hms(9, 42, 37)
export const END = hms(9, 42, 52)
export const RANGE_MS = 5 * 60_000

const EVENTS: NetEvent[] = [
  { at: STARTED, status: 'online', ip: IP },
  { at: DROP, status: 'lan' },
  { at: BACK, status: 'online', ip: IP },
]

/** h:mm:ss, as the extension shows durations. */
export function formatClockDuration(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

export function formatTime(ms: number) {
  const total = Math.floor(ms / 1000)
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  return `${h % 12 === 0 ? 12 : h % 12}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`
}

const isDown = (status: NetStatus) => status === 'offline' || status === 'lan'

function todayStats(events: NetEvent[], now: number) {
  let onlineMs = 0
  let downtimeMs = 0
  let disconnects = 0
  let previous: NetStatus | null = null
  events.forEach((event, i) => {
    const span = Math.min(now, events[i + 1]?.at ?? now) - event.at
    if (span <= 0) return
    if (event.status === 'online') onlineMs += span
    else if (isDown(event.status)) downtimeMs += span
    if (event.status !== 'nodata') {
      if (isDown(event.status) && previous === 'online') disconnects++
      previous = event.status
    }
  })
  const total = onlineMs + downtimeMs
  return { onlineMs, downtimeMs, disconnects, availability: total ? onlineMs / total : null }
}

export const formatAvailability = (value: number | null) =>
  value === null ? '—' : `${(value * 100).toFixed(2)}%`

export function availabilityColor(value: number | null) {
  if (value === null) return STATUS_COLOR.nodata
  if (value >= 0.99) return STATUS_COLOR.online
  if (value >= 0.95) return STATUS_COLOR.lan
  return STATUS_COLOR.offline
}

export const TODAY_BEFORE = todayStats(EVENTS, START)
export const TODAY_AFTER = todayStats(EVENTS, END)

function latencyAt(i: number) {
  const wave = Math.sin(i * 0.9) * 4 + Math.sin(i * 2.3) * 3
  const spike = i % 17 === 5 ? 38 : i % 23 === 11 ? 22 : 0
  return Math.round(24 + wave + spike)
}

export const SAMPLES: Sample[] = []
for (let at = END - RANGE_MS, i = 0; at <= END; at += INTERVAL_S * 1000, i++) {
  const down = at >= DROP && at < BACK
  const firstMiss = at === DROP - INTERVAL_S * 1000
  SAMPLES.push({
    at,
    status: down ? 'lan' : 'online',
    latency: down || firstMiss ? null : latencyAt(i),
  })
}

function summary(samples: Sample[]) {
  const values = samples.map((s) => s.latency).filter((v): v is number => v !== null)
  if (!values.length) return { avg: null, min: null, max: null }
  return {
    avg: values.reduce((a, b) => a + b, 0) / values.length,
    min: Math.min(...values),
    max: Math.max(...values),
  }
}

export const formatLatency = (ms: number | null) => (ms === null ? '—' : `${Math.round(ms)} ms`)

const upTo = (t: number) => SAMPLES.filter((s) => s.at <= t)
export const SUMMARY_START = { ...summary(upTo(START)), count: upTo(START).length }
export const SUMMARY_END = { ...summary(SAMPLES), count: SAMPLES.length }
export const lastLatency = (t: number) => upTo(t).at(-1)?.latency ?? null

export const CHART = { w: 268, h: 74 }
const xOf = (at: number) => ((at - (END - RANGE_MS)) / RANGE_MS) * CHART.w
const MAX_Y = 70
const yOf = (latency: number) => CHART.h - (Math.min(latency, MAX_Y) / MAX_Y) * (CHART.h - 6)
export const X_START = xOf(START)
export const X_DROP = xOf(DROP)
export const X_BACK = xOf(BACK)

export const LINE = (() => {
  let d = ''
  let pen = false
  for (const s of SAMPLES) {
    if (s.latency === null) {
      pen = false
      continue
    }
    d += `${pen ? 'L' : 'M'}${xOf(s.at).toFixed(1)} ${yOf(s.latency).toFixed(1)}`
    pen = true
  }
  return d
})()

export const xAt = xOf

/** What the panel shows at time `t` of the sample morning. */
export function stateAt(t: number) {
  const seen = upTo(t)
  const since = t >= BACK ? BACK : t >= DROP ? DROP : STARTED
  return {
    count: seen.length,
    latency: seen.at(-1)?.latency ?? null,
    forMs: t - since,
    summary: summary(seen),
    today: todayStats(
      EVENTS.filter((event) => event.at <= t),
      t,
    ),
  }
}

export type LogRow = {
  at: number
  status: NetStatus
  ip?: string
  durationMs: number
  short: string
}
export const LOG: LogRow[] = EVENTS.map((event, i) => ({
  ...event,
  durationMs: Math.max(0, (EVENTS[i + 1]?.at ?? END) - event.at),
  short: SHORT[event.status],
})).reverse()

const csvCell = (value: string) => (/[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value)
export const CSV = [
  ['Date and time', 'Status', 'Status duration', 'Your IP'].join(','),
  ...LOG.map((row) =>
    [
      `${DATE}, ${formatTime(row.at)}`,
      HUMAN[row.status],
      formatClockDuration(row.durationMs),
      row.ip ?? '',
    ]
      .map(csvCell)
      .join(','),
  ),
].join('\n')
export const CSV_FILE = 'internet-monitor-2026-10-24.csv'
